#!/usr/bin/env python3

from __future__ import annotations

import os
import re
import sys
from dataclasses import dataclass, field
from typing import Callable


DEFAULT_FONT_DIR = "/usr/local/share/figlet"
DEFAULT_FONT = "standard"
DEFAULT_OUTPUT_WIDTH = 80
GERMAN_CODES = [196, 214, 220, 228, 246, 252, 223]
GERMAN_MAP = {
    91: 196,   # [
    92: 214,   # \
    93: 220,   # ]
    123: 228,  # {
    124: 246,  # |
    125: 252,  # }
    126: 223,  # ~
}
SM_EQUAL = 1
SM_LOWLINE = 2
SM_HIERARCHY = 4
SM_PAIR = 8
SM_BIGX = 16
SM_HARDBLANK = 32
HIERARCHY_CLASSES = ["|", "/\\", "[]", "{}", "()", "<>"]
VERSION_TEXT = """FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,
Christiaan Keet and Claudio Matsuoka
Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012

FIGlet, along with the various FIGlet fonts and documentation, may be
freely copied and distributed.

If you use FIGlet, please send an e-mail message to <info@figlet.org>.

The latest version of FIGlet is available from the web site,
\thttp://www.figlet.org/
"""


class UsageError(Exception):
    def __init__(self, argv0: str, message: str) -> None:
        super().__init__(message)
        self.argv0 = argv0
        self.message = message


class FileOpenError(Exception):
    def __init__(self, kind: str, name: str) -> None:
        super().__init__(name)
        self.kind = kind
        self.name = name


@dataclass
class Font:
    hardblank: str
    height: int
    old_layout: int
    print_direction: int
    full_layout: int | None
    glyphs: dict[int, list[str]]

    def blank_glyph(self) -> list[str]:
        return [""] * self.height

    @property
    def font_rules(self) -> int:
        if self.full_layout is not None:
            layout = self.full_layout & 0xFF
            if layout & 0x80:
                return layout & 0x3F
            return 0
        if self.old_layout > 0:
            return self.old_layout & 0x3F
        return 0

    @property
    def default_layout(self) -> str:
        if self.full_layout is not None:
            layout = self.full_layout & 0xFF
            if layout & 0x80:
                return "smush"
            if layout & 0x40:
                return "kern"
            return "full"
        if self.old_layout == -1:
            return "full"
        if self.old_layout == 0:
            return "kern"
        if self.old_layout > 0:
            return "smush"
        return "full"


@dataclass
class ControlFile:
    transforms: list[Callable[[list[int]], list[int]]] = field(default_factory=list)

    def apply(self, values: list[int]) -> list[int]:
        result = values
        for transform in self.transforms:
            result = transform(result)
        return result


def usage_text(prog: str) -> str:
    return (
        f"Usage: {prog} [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n"
        "              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n"
        "              [ -C controlfile ] [ -I infocode ] [ message ]\n"
    )


def c_atoi(text: str) -> int:
    match = re.match(r"^[ \t\r\n\v\f]*([+-]?)(\d+)", text)
    if not match:
        return 0
    value = int(match.group(2), 10)
    if match.group(1) == "-":
        value = -value
    return value


def c_strtol_base0(text: str) -> int:
    stripped = text.strip()
    if not stripped:
        return 0
    sign = 1
    if stripped[0] in "+-":
        if stripped[0] == "-":
            sign = -1
        stripped = stripped[1:]
    if stripped.lower().startswith("0x"):
        try:
            return sign * int(stripped[2:], 16)
        except ValueError:
            return 0
    if len(stripped) > 1 and stripped.startswith("0"):
        try:
            return sign * int(stripped, 8)
        except ValueError:
            pass
    try:
        return sign * int(stripped, 10)
    except ValueError:
        return 0


def parse_short_options(argv: list[str]) -> tuple[list[tuple[str, str | None]], list[str]]:
    option_chars = set("cklnoprstvxDELNRSWXdfmwCI")
    needs_arg = {"d", "f", "m", "w", "C", "I"}
    options: list[tuple[str, str | None]] = []
    nonoptions: list[str] = []
    i = 1
    permute = True

    while i < len(argv):
        arg = argv[i]
        if permute and arg == "--":
            permute = False
            i += 1
            continue
        if (not permute) or arg == "-" or not arg.startswith("-"):
            nonoptions.append(arg)
            i += 1
            continue

        j = 1
        while j < len(arg):
            opt = arg[j]
            if opt not in option_chars:
                raise UsageError(argv[0], f"{argv[0]}: invalid option -- '{opt}'\n")
            if opt in needs_arg:
                if j + 1 < len(arg):
                    optarg = arg[j + 1 :]
                else:
                    if i + 1 >= len(argv):
                        raise UsageError(
                            argv[0],
                            f"{argv[0]}: option requires an argument -- '{opt}'\n",
                        )
                    i += 1
                    optarg = argv[i]
                options.append((opt, optarg))
                break
            options.append((opt, None))
            j += 1
        i += 1

    return options, nonoptions


def decode_font_file(path: str) -> Font:
    try:
        raw = open(path, "rb").read()
    except OSError as exc:
        raise FileOpenError("font", os.path.basename(path)) from exc

    text = raw.decode("utf-8", "surrogateescape")
    lines = text.splitlines()
    if not lines:
        raise FileOpenError("font", os.path.basename(path))

    header = lines[0]
    if len(header) < 6 or header[:5] not in {"flf2a", "tlf2a"}:
        raise FileOpenError("font", os.path.basename(path))

    hardblank = header[5]
    parts = header[6:].strip().split()
    if len(parts) < 5:
        raise FileOpenError("font", os.path.basename(path))

    height = int(parts[0])
    old_layout = int(parts[3])
    comment_lines = int(parts[4])
    print_direction = int(parts[5]) if len(parts) > 5 else 0
    full_layout = int(parts[6]) if len(parts) > 6 else None

    cursor = 1 + comment_lines
    glyphs: dict[int, list[str]] = {}

    def read_glyph() -> list[str]:
        nonlocal cursor
        glyph: list[str] = []
        for _ in range(height):
            if cursor >= len(lines):
                glyph.append("")
                continue
            line = lines[cursor]
            cursor += 1
            while line.endswith("@") or line.endswith(hardblank):
                if line.endswith("@") and header[:5] == "flf2a":
                    break
                if line.endswith(hardblank) and header[:5] == "tlf2a":
                    break
                break
            glyph.append(strip_fig_line(line, "@"))
        return glyph

    for code in range(32, 127):
        glyphs[code] = read_glyph()
    for code in GERMAN_CODES:
        glyphs[code] = read_glyph()

    while cursor < len(lines):
        tag_line = lines[cursor].strip()
        if not tag_line:
            cursor += 1
            continue
        cursor += 1
        token = tag_line.split()[0]
        code = c_strtol_base0(token)
        glyph = []
        for _ in range(height):
            if cursor >= len(lines):
                glyph.append("")
                continue
            glyph.append(strip_fig_line(lines[cursor], "@"))
            cursor += 1
        glyphs[code] = glyph

    return Font(
        hardblank=hardblank,
        height=height,
        old_layout=old_layout,
        print_direction=print_direction,
        full_layout=full_layout,
        glyphs=glyphs,
    )


def strip_fig_line(line: str, endmark: str) -> str:
    stripped = line
    while stripped.endswith(endmark):
        stripped = stripped[:-1]
    return stripped


def resolve_font_path(fontdir: str, name: str) -> str:
    candidates: list[str] = []
    if "/" in name:
        if name.endswith((".flf", ".tlf")):
            candidates.append(name)
        else:
            candidates.extend([name + ".flf", name + ".tlf"])
    else:
        names = [name] if name.endswith((".flf", ".tlf")) else [name + ".flf", name + ".tlf"]
        for base in names:
            candidates.append(os.path.join(fontdir, base))
        for base in names:
            candidates.append(base)

    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate
    raise FileOpenError("font", name)


def resolve_control_path(fontdir: str, name: str) -> str:
    candidates: list[str] = []
    if "/" in name:
        candidates.append(name if name.endswith(".flc") else name + ".flc")
    else:
        base = name if name.endswith(".flc") else name + ".flc"
        candidates.append(os.path.join(fontdir, base))
        candidates.append(base)
    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate
    raise FileOpenError("control", name)


def load_control_file(path: str) -> ControlFile:
    try:
        raw = open(path, "rb").read()
    except OSError as exc:
        raise FileOpenError("control", os.path.basename(path)) from exc

    text = raw.decode("utf-8", "surrogateescape")
    lines = text.splitlines()
    control = ControlFile()
    if not lines:
        return control

    header = lines[0].strip()
    if header == "flc2a":
        mapping: dict[int, int] = {}
        mode_seen = False
        for line in lines[1:]:
            bare = line.strip()
            if not bare or bare.startswith("#"):
                continue
            if bare == "u":
                mode_seen = True
                control.transforms.append(transform_utf8)
                continue
            if bare == "h":
                mode_seen = True
                control.transforms.append(lambda values: values)
                continue
            if bare == "f":
                continue

            content = bare.split("#", 1)[0].strip()
            if not content:
                continue
            if content.startswith("t "):
                content = content[2:].strip()
            parts = content.split()
            if len(parts) < 2:
                continue
            left_values = parse_control_token(parts[0])
            right_values = parse_control_token(parts[1])
            if not left_values or not right_values:
                continue
            if len(left_values) == 1 and len(right_values) == 1:
                mapping[left_values[0]] = right_values[0]
                continue
            if len(left_values) == len(right_values):
                for left, right in zip(left_values, right_values):
                    mapping[left] = right
                continue

        if mapping:
            control.transforms.append(make_mapping_transform(mapping))
        if not control.transforms and not mode_seen:
            control.transforms.append(lambda values: values)
        return control

    table: dict[int, int] = {}
    for line in lines:
        bare = line.strip()
        if not bare or bare.startswith("#"):
            continue
        content = bare.split("#", 1)[0].strip()
        parts = content.split()
        if len(parts) < 2:
            continue
        try:
            left = int(parts[0], 16)
            right = int(parts[1], 16)
        except ValueError:
            continue
        table[left] = right
    control.transforms.append(make_mapping_transform(table))
    return control


def make_mapping_transform(mapping: dict[int, int]) -> Callable[[list[int]], list[int]]:
    def transform(values: list[int]) -> list[int]:
        return [mapping.get(value, value) for value in values]

    return transform


def transform_utf8(values: list[int]) -> list[int]:
    raw = bytes(value & 0xFF for value in values)
    text = raw.decode("utf-8", "surrogateescape")
    result: list[int] = []
    for char in text:
        code = ord(char)
        if 0xDC80 <= code <= 0xDCFF:
            result.append(code - 0xDC00)
        else:
            result.append(code)
    return result


def parse_control_token(token: str) -> list[int]:
    if "-" in token and not token.startswith(r"\-"):
        index = find_range_dash(token)
        if index > 0:
            start = parse_control_scalar(token[:index])
            end = parse_control_scalar(token[index + 1 :])
            if start is None or end is None:
                return []
            step = 1 if end >= start else -1
            return list(range(start, end + step, step))

    scalar = parse_control_scalar(token)
    return [] if scalar is None else [scalar]


def find_range_dash(token: str) -> int:
    escaped = False
    for index, char in enumerate(token):
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if char == "-":
            return index
    return -1


def parse_control_scalar(token: str) -> int | None:
    if not token:
        return None
    if token.startswith(r"\0x"):
        hex_parts = re.findall(r"\\0x([0-9A-Fa-f]+)", token)
        if hex_parts and "".join(rf"\0x{part}" for part in hex_parts) == token:
            return int("".join(hex_parts), 16)
    if token.startswith("\\"):
        inner = token[1:]
        if inner.lower().startswith("0x"):
            try:
                return int(inner[2:], 16)
            except ValueError:
                return None
        match = re.fullmatch(r"(-?\d+)", inner)
        if match:
            return int(match.group(1), 10)
    if len(token) == 1:
        return ord(token)
    return None


def apply_paragraph_mode(values: list[int]) -> list[int]:
    result = values[:]
    for index, value in enumerate(result):
        if value != 10:
            continue
        prev_value = result[index - 1] if index > 0 else None
        next_value = result[index + 1] if index + 1 < len(result) else None
        if prev_value != 10 and next_value != 32:
            result[index] = 32
    return result


def apply_german(values: list[int], enabled: bool) -> list[int]:
    if not enabled:
        return values
    return [GERMAN_MAP.get(value, value) for value in values]


def block_width(block: list[str]) -> int:
    return max((len(row) for row in block), default=0)


def render_text(
    font: Font,
    values: list[int],
    output_width: int,
    justification: str,
    direction: int,
    mode: str,
    rules: int,
) -> str:
    if not values:
        return ""

    rows: list[str] = []
    current_line: list[int] = []

    for value in values:
        if value == 10:
            rows.extend(
                render_logical_line(
                    font,
                    current_line,
                    output_width,
                    justification,
                    direction,
                    mode,
                    rules,
                )
            )
            current_line = []
            continue
        current_line.append(value)

    if current_line:
        rows.extend(
            render_logical_line(
                font,
                current_line,
                output_width,
                justification,
                direction,
                mode,
                rules,
            )
        )

    return "".join(f"{row}\n" for row in rows)


def render_logical_line(
    font: Font,
    values: list[int],
    output_width: int,
    justification: str,
    direction: int,
    mode: str,
    rules: int,
) -> list[str]:
    if output_width == 1:
        return render_width_one(font, values, output_width, justification, direction, mode, rules)
    if not values:
        return [justify_row("", output_width, justification)] * font.height

    available = max(output_width - 1, 0)
    blocks: list[list[str]] = []
    current: list[int] = []
    current_space = -1
    index = 0

    while index < len(values):
        candidate = current + [values[index]]
        rendered = render_sequence(font, candidate, direction, mode, rules)
        if not current or block_width(rendered) <= available:
            current = candidate
            if values[index] == 32:
                current_space = len(current) - 1
            index += 1
            continue

        if current_space >= 0:
            emit = current[:current_space]
            if emit:
                blocks.append(render_sequence(font, emit, direction, mode, rules))
            current = current[current_space + 1 :]
            current_space = find_last_space(current)
            if not current:
                if values[index] == 32:
                    index += 1
                continue
            continue

        blocks.append(render_sequence(font, current, direction, mode, rules))
        current = []
        current_space = -1

    if current:
        blocks.append(render_sequence(font, current, direction, mode, rules))

    output: list[str] = []
    for block in blocks:
        output.extend(justify_block(block, output_width, justification, font.hardblank))
    return output


def render_width_one(
    font: Font,
    values: list[int],
    output_width: int,
    justification: str,
    direction: int,
    mode: str,
    rules: int,
) -> list[str]:
    if not values:
        return [justify_row("", output_width, justification)] * font.height

    blocks: list[list[str]] = []
    pending_spaces = 0
    seen_nonspace = False

    for value in values:
        if value == 32:
            if not seen_nonspace:
                pending_spaces += 1
            continue
        if pending_spaces:
            blocks.append(render_sequence(font, [32] * pending_spaces, direction, mode, rules))
            pending_spaces = 0
        blocks.append(render_sequence(font, [value], direction, mode, rules))
        seen_nonspace = True

    if pending_spaces and not seen_nonspace:
        blocks.append(render_sequence(font, [32] * pending_spaces, direction, mode, rules))

    output: list[str] = []
    for block in blocks:
        output.extend(justify_block(block, output_width, justification, font.hardblank))
    return output


def justify_block(block: list[str], output_width: int, justification: str, hardblank: str) -> list[str]:
    return [justify_row(row.replace(hardblank, " "), output_width, justification) for row in block]


def justify_row(row: str, output_width: int, justification: str) -> str:
    if output_width == 1:
        return row
    available = max(output_width - 1, 0)
    clipped = row[:available]
    if justification == "l":
        return clipped
    if justification == "c":
        padding = max((available - len(clipped)) // 2, 0)
        return (" " * padding) + clipped
    if justification == "r":
        padding = max(available - len(clipped), 0)
        return (" " * padding) + clipped
    return clipped


def find_last_space(values: list[int]) -> int:
    for index in range(len(values) - 1, -1, -1):
        if values[index] == 32:
            return index
    return -1


def render_sequence(font: Font, values: list[int], direction: int, mode: str, rules: int) -> list[str]:
    current = font.blank_glyph()
    empty = True
    for value in values:
        glyph = font.glyphs.get(value, font.blank_glyph())
        if empty:
            current = glyph[:]
            empty = False
            continue
        if direction == 0:
            current = merge_blocks(font, current, glyph, mode, rules, rtl=False)
        else:
            current = merge_blocks(font, glyph, current, mode, rules, rtl=True)
    if empty:
        return font.blank_glyph()
    return current


def merge_blocks(
    font: Font,
    left: list[str],
    right: list[str],
    mode: str,
    rules: int,
    rtl: bool,
) -> list[str]:
    if mode == "full":
        return [lrow + rrow for lrow, rrow in zip(left, right)]

    effective_left = left
    effective_right = right
    effective_mode = mode

    if mode == "smush" and rules == 0:
        effective_mode = "overlap"

    if effective_mode == "overlap":
        if rtl:
            if block_width(left) > 1 and any(right):
                effective_left = [row[:-1] if row else row for row in left]
        else:
            if block_width(right) > 1 and any(left):
                effective_right = [row[1:] if row else row for row in right]
        effective_mode = "kern"

    overlap = calculate_overlap(font, effective_left, effective_right, effective_mode, rules)
    result: list[str] = []
    for left_row, right_row in zip(effective_left, effective_right):
        result.append(merge_rows(font, left_row, right_row, overlap, effective_mode, rules))
    return result


def calculate_overlap(
    font: Font,
    left: list[str],
    right: list[str],
    mode: str,
    rules: int,
) -> int:
    if mode == "full":
        return 0
    max_overlap = max((len(row) for row in left), default=0)
    best = 0
    for overlap in range(1, max_overlap + 1):
        if all(can_overlap_rows(font, lrow, rrow, overlap, mode, rules) for lrow, rrow in zip(left, right)):
            best = overlap
        else:
            break
    return best


def can_overlap_rows(
    font: Font,
    left_row: str,
    right_row: str,
    overlap: int,
    mode: str,
    rules: int,
) -> bool:
    start = len(left_row) - overlap
    for r_index, r_char in enumerate(right_row):
        l_index = start + r_index
        if l_index < 0 or l_index >= len(left_row):
            continue
        l_char = left_row[l_index]
        if l_char == " " or r_char == " ":
            continue
        if mode == "kern":
            return False
        if mode == "smush" and smush_chars(font.hardblank, l_char, r_char, rules) is None:
            return False
    return True


def merge_rows(
    font: Font,
    left_row: str,
    right_row: str,
    overlap: int,
    mode: str,
    rules: int,
) -> str:
    if overlap <= 0:
        return left_row + right_row

    start = len(left_row) - overlap
    out: list[str] = []
    max_length = max(len(left_row), start + len(right_row))
    for index in range(max_length):
        left_char = left_row[index] if 0 <= index < len(left_row) else " "
        right_index = index - start
        right_char = right_row[right_index] if 0 <= right_index < len(right_row) else " "
        if right_index < 0 or right_index >= len(right_row):
            out.append(left_char)
            continue
        if index < 0 or index >= len(left_row):
            out.append(right_char)
            continue
        if left_char == " ":
            out.append(right_char)
        elif right_char == " ":
            out.append(left_char)
        elif mode == "smush":
            smushed = smush_chars(font.hardblank, left_char, right_char, rules)
            out.append(smushed if smushed is not None else left_char)
        else:
            out.append(left_char)
    return "".join(out)


def smush_chars(hardblank: str, left: str, right: str, rules: int) -> str | None:
    if left == " ":
        return right
    if right == " ":
        return left
    if left == hardblank or right == hardblank:
        if left == right == hardblank and (rules & SM_HARDBLANK):
            return hardblank
        return None
    if (rules & SM_EQUAL) and left == right:
        return left
    if rules & SM_LOWLINE:
        hierarchy_chars = "|/\\[]{}()<>"
        if left == "_" and right in hierarchy_chars:
            return right
        if right == "_" and left in hierarchy_chars:
            return left
    if rules & SM_HIERARCHY:
        left_class = hierarchy_class(left)
        right_class = hierarchy_class(right)
        if left_class >= 0 and right_class >= 0 and left_class != right_class:
            return left if left_class > right_class else right
    if rules & SM_PAIR:
        if (left, right) in {("[", "]"), ("]", "["), ("{", "}"), ("}", "{"), ("(", ")"), (")", "(")}:
            return "|"
    if rules & SM_BIGX:
        if (left, right) == ("/", "\\"):
            return "|"
        if (left, right) == ("\\", "/"):
            return "Y"
        if (left, right) == (">", "<"):
            return "X"
    return None


def hierarchy_class(char: str) -> int:
    for index, chars in enumerate(HIERARCHY_CLASSES):
        if char in chars:
            return index
    return -1


def determine_terminal_width(current_width: int) -> int:
    try:
        return os.get_terminal_size(sys.stdout.fileno()).columns
    except OSError:
        return current_width


def info_output(code: int, prog: str, fontdir: str, fontname: str, width: int) -> str:
    if code == 0:
        return VERSION_TEXT + usage_text(prog)
    if code == 1:
        return "20205\n"
    if code == 2:
        return f"{fontdir}\n"
    if code == 3:
        return f"{fontname}\n"
    if code == 4:
        return f"{width}\n"
    if code == 5:
        return "flf2 tlf2\n"
    return ""


def main(argv: list[str]) -> int:
    prog = os.path.basename(argv[0])
    try:
        parsed_options, message_args = parse_short_options(argv)
    except UsageError as exc:
        sys.stderr.write(exc.message)
        sys.stderr.write(usage_text(prog))
        return 1

    fontdir = DEFAULT_FONT_DIR
    fontname = DEFAULT_FONT
    output_width = DEFAULT_OUTPUT_WIDTH
    justification = "x"
    paragraph_mode = False
    direction = "X"
    german_mode = False
    controls: list[str] = []
    info_code = -1
    mode = "default"
    explicit_rules = 0

    for opt, value in parsed_options:
        if opt == "d":
            fontdir = value or fontdir
        elif opt == "f":
            fontname = value or fontname
        elif opt == "c":
            justification = "c"
        elif opt == "l":
            justification = "l"
        elif opt == "r":
            justification = "r"
        elif opt == "x":
            justification = "x"
        elif opt == "p":
            paragraph_mode = True
        elif opt == "n":
            paragraph_mode = False
        elif opt == "L":
            direction = "L"
        elif opt == "R":
            direction = "R"
        elif opt == "X":
            direction = "X"
        elif opt == "D":
            german_mode = True
        elif opt == "E":
            german_mode = False
        elif opt == "C":
            controls.append(value or "")
        elif opt == "N":
            controls = []
        elif opt == "t":
            output_width = determine_terminal_width(output_width)
        elif opt == "w":
            width = c_atoi(value or "")
            if width > 0:
                output_width = width
        elif opt == "W":
            mode = "full"
        elif opt == "k":
            mode = "kern"
        elif opt == "o":
            mode = "overlap"
        elif opt == "s":
            mode = "default"
        elif opt == "S":
            mode = "force-smush"
        elif opt == "m":
            smushmode = c_atoi(value or "")
            if smushmode == -1:
                mode = "full"
            elif smushmode == 0:
                mode = "kern"
            elif smushmode == -2:
                mode = "default"
            elif smushmode > 0:
                mode = "explicit-smush"
                explicit_rules = smushmode & 0x3F
        elif opt == "v":
            info_code = 0
        elif opt == "I":
            info_code = c_atoi(value or "")

    if info_code >= 0:
        sys.stdout.write(info_output(info_code, prog, fontdir, fontname, output_width))
        return 0

    try:
        font_path = resolve_font_path(fontdir, fontname)
        font = decode_font_file(font_path)
        control_files = [load_control_file(resolve_control_path(fontdir, name)) for name in controls]
    except FileOpenError as exc:
        if exc.kind == "font":
            sys.stderr.write(f"{prog}: {exc.name}: Unable to open font file\n")
        else:
            sys.stderr.write(f"{prog}: {exc.name}: Unable to open control file\n")
        return 1

    if direction == "L":
        render_direction = 0
    elif direction == "R":
        render_direction = 1
    else:
        render_direction = 1 if font.print_direction == 1 else 0

    if justification == "x":
        render_justification = "r" if render_direction == 1 else "l"
    else:
        render_justification = justification

    if mode == "full":
        render_mode = "full"
        render_rules = 0
    elif mode == "kern":
        render_mode = "kern"
        render_rules = 0
    elif mode == "overlap":
        render_mode = "overlap"
        render_rules = 0
    elif mode == "force-smush":
        render_mode = "smush"
        render_rules = font.font_rules
    elif mode == "explicit-smush":
        render_mode = "smush"
        render_rules = explicit_rules
    else:
        render_mode = font.default_layout
        render_rules = font.font_rules

    if render_mode == "smush" and render_rules == 0 and font.default_layout != "smush":
        render_mode = "kern"

    if message_args:
        raw_input = build_message_input(message_args)
    else:
        raw_input = sys.stdin.buffer.read()

    values = list(raw_input)
    if paragraph_mode:
        values = apply_paragraph_mode(values)
    values = apply_german(values, german_mode)
    for control in control_files:
        values = control.apply(values)

    output = render_text(
        font,
        values,
        output_width,
        render_justification,
        render_direction,
        render_mode,
        render_rules,
    )
    sys.stdout.write(output)
    return 0


def build_message_input(args: list[str]) -> bytes:
    output = bytearray()
    at_line_start = True
    for arg in args:
        raw = os.fsencode(arg)
        if raw == b"":
            output.extend(b"\n")
            at_line_start = True
            continue
        if not at_line_start:
            output.extend(b" ")
        output.extend(raw)
        at_line_start = False
    return bytes(output)


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

