def atoi_like(value: str) -> int:
    match = re.match(r"\s*([+-]?)(\d+)", value)
    if not match:
        return 0
    number = int(match.group(2))
    if match.group(1) == "-":
        return -number
    return number


def strip_known_suffix(path: str, suffixes: Sequence[str]) -> str:
    for suffix in suffixes:
        if path.endswith(suffix):
            return path[: -len(suffix)]
    return path


def is_path_like(name: str) -> bool:
    return "/" in name


def usage_text(prog_name: str) -> str:
    return USAGE_TEMPLATE.format(prog=prog_name)


def read_archive_or_plain(path: str) -> bytes:
    with open(path, "rb") as handle:
        data = handle.read()
    if data.startswith(b"PK\x03\x04"):
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            for info in archive.infolist():
                if not info.is_dir():
                    return archive.read(info)
            raise FileNotFoundError(path)
    return data


@dataclass
class Font:
    name: str
    hardblank: str
    height: int
    old_layout: int
    print_direction: int
    horizontal_layout: int
    glyphs: Dict[int, List[str]]

    @property
    def empty_rows(self) -> List[str]:
        return [""] * self.height


@dataclass
class ControlFile:
    translate: Dict[int, int]
    utf8_mode: bool


def decode_text(data: bytes) -> str:
    return data.decode("utf-8", "surrogateescape")


def strip_fig_row(raw: str, hardblank: str) -> str:
    if not raw:
        return raw
    endmark = raw[-1]
    idx = len(raw)
    while idx > 0 and raw[idx - 1] == endmark:
        idx -= 1
    row = raw[:idx]
    while row.endswith(hardblank):
        row = row[:-1]
    return row


def normalize_rows(rows: List[str]) -> List[str]:
    width = max((len(row) for row in rows), default=0)
    return [row.ljust(width) for row in rows]


def parse_font(path: str, display_name: str) -> Font:
    try:
        raw = read_archive_or_plain(path)
    except OSError as exc:
        raise FileNotFoundError(display_name) from exc
    lines = decode_text(raw).splitlines()
    if not lines:
        raise ValueError(display_name)
    header_parts = lines[0].split()
    if len(header_parts) < 6:
        raise ValueError(display_name)
    magic = header_parts[0]
    if len(magic) < 6 or magic[:5] not in {"flf2a", "tlf2a"}:
        raise ValueError(display_name)
    hardblank = magic[-1]
    try:
        height = int(header_parts[1])
        old_layout = int(header_parts[4])
        comment_lines = int(header_parts[5])
        print_direction = int(header_parts[6]) if len(header_parts) > 6 else 0
        full_layout = int(header_parts[7]) if len(header_parts) > 7 else 0
    except ValueError as exc:
        raise ValueError(display_name) from exc
    if height < 1:
        raise ValueError(display_name)
    if full_layout:
        horizontal_layout = full_layout & 0xFF
    elif old_layout == -1:
        horizontal_layout = 0
    elif old_layout == 0:
        horizontal_layout = 0x40
    elif old_layout > 0:
        horizontal_layout = 0x80 | old_layout
    else:
        horizontal_layout = 0
    body = lines[1 + comment_lines :]
    glyphs: Dict[int, List[str]] = {}
    required = list(range(32, 127)) + [196, 214, 220, 228, 246, 252, 223]
    index = 0
    for codepoint in required:
        if index + height > len(body):
            raise ValueError(display_name)
        rows = [strip_fig_row(body[index + row], hardblank) for row in range(height)]
        glyphs[codepoint] = normalize_rows(rows)
        index += height
    while index < len(body):
        tag_line = body[index].strip()
        index += 1
        if not tag_line:
            continue
        token = tag_line.split()[0]
        try:
            if token.lower().startswith("0x"):
                codepoint = int(token, 16)
            else:
                codepoint = int(token, 10)
        except ValueError:
            continue
        if index + height > len(body):
            break
        rows = [strip_fig_row(body[index + row], hardblank) for row in range(height)]
        glyphs[codepoint] = normalize_rows(rows)
        index += height
    return Font(
        name=display_name,
        hardblank=hardblank,
        height=height,
        old_layout=old_layout,
        print_direction=1 if print_direction == 1 else 0,
        horizontal_layout=horizontal_layout,
        glyphs=glyphs,
    )


def consume_control_atom(token: str, start: int = 0) -> Optional[Tuple[int, int]]:
    if start >= len(token):
        return None
    if token[start] != "\\":
        return ord(token[start]), start + 1
    if token.startswith("\\0x", start):
        idx = start
        parts: List[str] = []
        while token.startswith("\\0x", idx):
            idx += 3
            begin = idx
            while idx < len(token) and token[idx] in "0123456789abcdefABCDEF":
                idx += 1
            if begin == idx:
                return None
            parts.append(token[begin:idx])
        return int("".join(parts), 16), idx
    if token.startswith("\\-", start):
        idx = start + 2
        begin = idx
        while idx < len(token) and token[idx].isdigit():
            idx += 1
        if begin == idx:
            return None
        return -int(token[begin:idx]), idx
    idx = start + 1
    if idx < len(token) and token[idx].isdigit():
        begin = idx
        while idx < len(token) and token[idx].isdigit():
            idx += 1
        return int(token[begin:idx], 8), idx
    if idx >= len(token):
        return None
    return ord(token[idx]), idx + 1


def parse_control_spec(token: str) -> Optional[Tuple[str, int, Optional[int]]]:
    first = consume_control_atom(token, 0)
    if first is None:
        return None
    value, index = first
    if index == len(token):
        return ("single", value, None)
    if token[index] == "-":
        second = consume_control_atom(token, index + 1)
        if second is not None and second[1] == len(token):
            return ("range", value, second[0])
    return None


def expand_control_pair(left: Tuple[str, int, Optional[int]], right: Tuple[str, int, Optional[int]]) -> Dict[int, int]:
    if left[0] == "single" and right[0] == "single":
        return {left[1]: right[1]}
    if left[0] == "range" and right[0] == "range":
        left_end = left[2]
        right_end = right[2]
        if left_end is None or right_end is None:
            return {}
        left_step = 1 if left_end >= left[1] else -1
        right_step = 1 if right_end >= right[1] else -1
        left_values = list(range(left[1], left_end + left_step, left_step))
        right_values = list(range(right[1], right_end + right_step, right_step))
        if len(left_values) != len(right_values):
            return {}
        return dict(zip(left_values, right_values))
    return {}


def parse_control_file(path: str, display_name: str) -> ControlFile:
    try:
        raw = read_archive_or_plain(path)
    except OSError as exc:
        raise FileNotFoundError(display_name) from exc
    text = decode_text(raw)
    translate: Dict[int, int] = {}
    utf8_mode = False
    for raw_line in text.splitlines():
        line = raw_line
        if "#" in line:
            line = line.split("#", 1)[0]
        line = line.strip()
        if not line or line == "flc2a":
            continue
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "u":
            utf8_mode = True
            continue
        if parts[0] in {"g", "h", "f"}:
            continue
        if parts[0] == "t" and len(parts) >= 3:
            left = parse_control_spec(parts[1])
            right = parse_control_spec(parts[2])
            if left and right:
                translate.update(expand_control_pair(left, right))
            continue
        if len(parts) >= 2:
            left = parse_control_spec(parts[0])
            right = parse_control_spec(parts[1])
            if left and right:
                translate.update(expand_control_pair(left, right))
    return ControlFile(translate=translate, utf8_mode=utf8_mode)


def resolve_font_path(name: str, fontdir: str, cwd: str) -> Tuple[str, str]:
    display_name = strip_known_suffix(name, (".flf", ".tlf"))
    candidates: List[str] = []
    if is_path_like(name):
        if name.endswith((".flf", ".tlf")):
            candidates = [name]
        else:
            candidates = [name, name + ".flf", name + ".tlf"]
    else:
        if name.endswith((".flf", ".tlf")):
            candidates = [os.path.join(fontdir, name), os.path.join(cwd, name)]
        else:
            candidates = [
                os.path.join(fontdir, name + ".flf"),
                os.path.join(fontdir, name + ".tlf"),
                os.path.join(cwd, name + ".flf"),
                os.path.join(cwd, name + ".tlf"),
            ]
    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate, display_name
    raise FileNotFoundError(display_name)


def resolve_control_path(name: str, fontdir: str, cwd: str) -> Tuple[str, str]:
    display_name = strip_known_suffix(name, (".flc",))
    candidates: List[str] = []
    if is_path_like(name):
        if name.endswith(".flc"):
            candidates = [name]
        else:
            candidates = [name, name + ".flc"]
    else:
        if name.endswith(".flc"):
            candidates = [os.path.join(fontdir, name), os.path.join(cwd, name)]
        else:
            candidates = [os.path.join(fontdir, name + ".flc"), os.path.join(cwd, name + ".flc")]
    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate, display_name
    raise FileNotFoundError(display_name)


def apply_german(codepoint: int, german: bool) -> int:
    if german:
        return GERMAN_MAP.get(codepoint, codepoint)
    return codepoint


def decode_utf8_bytes(data: bytes) -> List[int]:
    text = data.decode("utf-8", "surrogateescape")
    result: List[int] = []
    for char in text:
        codepoint = ord(char)
        if 0xDC80 <= codepoint <= 0xDCFF:
            result.append(codepoint - 0xDC00)
        else:
            result.append(codepoint)
    return result


def normalize_input_bytes(data: bytes) -> bytes:
    result = bytearray()
    for byte in data:
        if byte == 0x09:
            result.append(0x20)
        elif byte in {0x0B, 0x0C, 0x0D}:
            result.append(0x0A)
        else:
            result.append(byte)
    return bytes(result)


def paragraph_transform(data: bytes) -> bytes:
    result = bytearray()
    for index, byte in enumerate(data):
        if byte != 0x0A:
            result.append(byte)
            continue
        previous = data[index - 1] if index > 0 else None
        following = data[index + 1] if index + 1 < len(data) else None
        if previous != 0x0A and following != 0x20:
            result.append(0x20)
        else:
            result.append(0x0A)
    return bytes(result)


def build_argument_input(arguments: Sequence[str]) -> bytes:
    result = bytearray()
    for index, argument in enumerate(arguments):
        if argument == "":
            if index > 0 or index < len(arguments) - 1:
                result.append(0x0A)
            continue
        raw = os.fsencode(argument)
        if result and result[-1] not in {0x0A, 0x20}:
            result.append(0x20)
        result.extend(raw)
    return bytes(result)


def line_codepoints(data: bytes, controls: Sequence[ControlFile], german: bool) -> List[int]:
    utf8_mode = any(control.utf8_mode for control in controls)
    if utf8_mode:
        codepoints = decode_utf8_bytes(data)
    else:
        codepoints = list(data)
    result: List[int] = []
    for codepoint in codepoints:
        codepoint = apply_german(codepoint, german)
        for control in controls:
            codepoint = control.translate.get(codepoint, codepoint)
        result.append(codepoint)
    return result


def determine_layout(mode: Tuple[str, Optional[int]], font: Font) -> int:
    kind, value = mode
    if kind == "full":
        return 0
    if kind == "kern":
        return 0x40
    if kind == "overlap":
        return 0x80
    if kind == "explicit":
        return 0x80 | (value or 0)
    if kind == "force_smush":
        default_layout = font.horizontal_layout
        if default_layout & 0x80:
            return default_layout
        if font.old_layout > 0:
            return 0x80 | font.old_layout
        return 0x80
    return font.horizontal_layout


def glyph_for(font: Font, codepoint: int) -> List[str]:
    glyph = font.glyphs.get(codepoint)
    if glyph is None:
        return font.empty_rows
    return glyph


def can_merge_chars(left: str, right: str, layout: int, hardblank: str) -> Optional[str]:
    if left == " ":
        return right
    if right == " ":
        return left
    if not (layout & 0x80):
        return None
    rules = layout & 0x7F
    if left == hardblank and right == hardblank:
        if rules & 32:
            return hardblank
        return None
    if rules == 0 or rules == 64:
        return left
    if (rules & 1) and left == right:
        return left
    if rules & 2:
        if left == "_" and right in HIERARCHY:
            return right
        if right == "_" and left in HIERARCHY:
            return left
    if rules & 4:
        left_class = HIERARCHY.get(left)
        right_class = HIERARCHY.get(right)
        if left_class and right_class and left_class != right_class:
            return left if left_class > right_class else right
    if (rules & 8) and (left, right) in OPPOSITE_PAIRS:
        return "|"
    if rules & 16:
        if left == "/" and right == "\\":
            return "|"
        if left == "\\" and right == "/":
            return "Y"
        if left == ">" and right == "<":
            return "X"
    if rules & 32 and left == hardblank and right == hardblank:
        return hardblank
    return None


def can_shift(left_rows: List[str], right_rows: List[str], shift: int, layout: int, hardblank: str, allow_smush: bool) -> bool:
    left_width = len(left_rows[0]) if left_rows else 0
    right_width = len(right_rows[0]) if right_rows else 0
    start = left_width - shift
    for row_index in range(len(left_rows)):
        left_row = left_rows[row_index]
        right_row = right_rows[row_index]
        for right_pos in range(right_width):
            left_pos = start + right_pos
            if left_pos < 0 or left_pos >= left_width:
                continue
            left_char = left_row[left_pos]
            right_char = right_row[right_pos]
            if left_char == " " or right_char == " ":
                continue
            if not allow_smush:
                return False
            if can_merge_chars(left_char, right_char, layout, hardblank) is None:
                return False
    return True


def merge_rows(left_rows: List[str], right_rows: List[str], shift: int, layout: int, hardblank: str) -> List[str]:
    left_width = len(left_rows[0]) if left_rows else 0
    right_width = len(right_rows[0]) if right_rows else 0
    start = left_width - shift
    left_pad = max(0, -start)
    right_start = start + left_pad
    total_width = max(left_pad + left_width, right_start + right_width)
    merged: List[str] = []
    for row_index in range(len(left_rows)):
        base_row = (" " * left_pad + left_rows[row_index]).ljust(total_width)
        chars = list(base_row)
        right_row = right_rows[row_index]
        for right_pos, right_char in enumerate(right_row):
            position = right_start + right_pos
            current = chars[position]
            if current == " ":
                chars[position] = right_char
                continue
            if right_char == " ":
                continue
            replacement = can_merge_chars(current, right_char, layout, hardblank)
            chars[position] = replacement if replacement is not None else current
        merged.append("".join(chars))
    return normalize_rows(merged)


def append_glyph(current_rows: List[str], glyph_rows: List[str], layout: int, hardblank: str) -> List[str]:
    if not current_rows:
        return glyph_rows
    if not glyph_rows:
        return current_rows
    if len(current_rows[0]) == 0:
        return glyph_rows
    if len(glyph_rows[0]) == 0:
        return current_rows
    if layout == 0:
        return normalize_rows([left + right for left, right in zip(current_rows, glyph_rows)])
    shift = 0
    while can_shift(current_rows, glyph_rows, shift + 1, layout, hardblank, allow_smush=False):
        shift += 1
    if layout & 0x80 and len(glyph_rows[0]) > 1:
        if can_shift(current_rows, glyph_rows, shift + 1, layout, hardblank, allow_smush=True):
            shift += 1
    return merge_rows(current_rows, glyph_rows, shift, layout, hardblank)


def render_codepoints(codepoints: Sequence[int], font: Font, layout: int) -> List[str]:
    rows = [""] * font.height
    for codepoint in codepoints:
        rows = append_glyph(rows, glyph_for(font, codepoint), layout, font.hardblank)
    return rows


def wrap_codepoints(codepoints: List[int], font: Font, layout: int, output_width: int) -> List[List[int]]:
    if not codepoints:
        return [[]]
    segments: List[List[int]] = []
    current: List[int] = []
    for codepoint in codepoints:
        trial = current + [codepoint]
        trial_rows = render_codepoints(trial, font, layout)
        trial_width = len(trial_rows[0]) if trial_rows else 0
        if not current or output_width <= 0 or trial_width <= output_width:
            current = trial
            continue
        last_space = -1
        for idx, value in enumerate(current):
            if value == 0x20:
                last_space = idx
        if last_space != -1:
            head = current[:last_space]
            tail = current[last_space + 1 :]
            if head:
                segments.append(head)
            current = tail + [codepoint]
        else:
            segments.append(current)
            current = [codepoint]
    if current:
        segments.append(current)
    return segments


def justify_rows(rows: List[str], mode: str, rtl: bool, width: int, hardblank: str) -> List[str]:
    if not rows:
        return rows
    figure_width = len(rows[0])
    if mode == "left":
        padding = 0
    elif mode == "right":
        padding = max(0, width - figure_width)
    elif mode == "center":
        padding = max(0, (width - figure_width) // 2)
    else:
        padding = max(0, width - figure_width) if rtl else 0
    prefix = " " * padding
    return [(prefix + row).replace(hardblank, " ") for row in rows]


def render_input(
    input_bytes: bytes,
    font: Font,
    controls: Sequence[ControlFile],
    paragraph_mode: bool,
    german: bool,
    rtl: bool,
    justify: str,
    output_width: int,
    layout: int,
) -> List[str]:
    data = normalize_input_bytes(input_bytes)
    if paragraph_mode:
        data = paragraph_transform(data)
    if not data:
        return []
    parts = data.split(b"\n")
    if data.endswith(b"\n"):
        parts = parts[:-1]
    output_lines: List[str] = []
    for part in parts:
        codepoints = line_codepoints(part, controls, german)
        if rtl:
            codepoints.reverse()
        for segment in wrap_codepoints(codepoints, font, layout, output_width):
            rows = render_codepoints(segment, font, layout)
            output_lines.extend(justify_rows(rows, justify, rtl, output_width, font.hardblank))
    return output_lines


def terminal_width(previous: int) -> int:
    try:
        if not os.isatty(sys.stdout.fileno()):
            return previous
    except OSError:
        return previous
    try:
        return os.get_terminal_size(sys.stdout.fileno()).columns
    except OSError:
        return previous


def write_error(message: str) -> None:
    sys.stderr.write(message)


def main() -> int:
    argv0 = sys.argv[0]
    prog_name = os.path.basename(argv0)
    fontdir = os.environ.get("FIGLET_FONTDIR", DEFAULT_FONTDIR)
    font_name = DEFAULT_FONT
    paragraph_mode = False
    german = False
    justify = "auto"
    direction: Optional[bool] = None
    output_width = DEFAULT_WIDTH
    layout_mode: Tuple[str, Optional[int]] = ("default", None)
    info_code = -1
    controls_requested: List[str] = []
    operands: List[str] = []
    stop_options = False

    args = sys.argv[1:]
    index = 0
    while index < len(args):
        argument = args[index]
        if stop_options or argument == "" or argument == "-" or not argument.startswith("-"):
            operands.append(argument)
            index += 1
            continue
        if argument == "--":
            stop_options = True
            index += 1
            continue
        option_index = 1
        while option_index < len(argument):
            option = argument[option_index]
            if option == "F":
                write_error(f"{prog_name}: illegal option -- F\n")
                write_error(usage_text(prog_name))
                write_error("\n")
                write_error(REMOVED_F_TEXT)
                return 1
            if option in "AcklnoprstvxDELNRSWX":
                if option == "A":
                    pass
                elif option == "c":
                    justify = "center"
                elif option == "k":
                    layout_mode = ("kern", None)
                elif option == "l":
                    justify = "left"
                elif option == "n":
                    paragraph_mode = False
                elif option == "o":
                    layout_mode = ("overlap", None)
                elif option == "p":
                    paragraph_mode = True
                elif option == "r":
                    justify = "right"
                elif option == "s":
                    layout_mode = ("default", None)
                elif option == "t":
                    output_width = terminal_width(output_width)
                elif option == "v":
                    info_code = 0
                elif option == "x":
                    justify = "auto"
                elif option == "D":
                    german = True
                elif option == "E":
                    german = False
                elif option == "L":
                    direction = False
                elif option == "N":
                    controls_requested = []
                elif option == "R":
                    direction = True
                elif option == "S":
                    layout_mode = ("force_smush", None)
                elif option == "W":
                    layout_mode = ("full", None)
                elif option == "X":
                    direction = None
                option_index += 1
                continue
            if option in "dfmwCI":
                if option_index + 1 < len(argument):
                    value = argument[option_index + 1 :]
                    index_delta = 0
                elif index + 1 < len(args):
                    value = args[index + 1]
                    index_delta = 1
                else:
                    write_error(f"{argv0}: option requires an argument -- '{option}'\n")
                    write_error(usage_text(prog_name))
                    return 1
                if option == "d":
                    fontdir = value
                elif option == "f":
                    font_name = strip_known_suffix(value, (".flf", ".tlf"))
                elif option == "m":
                    parsed = atoi_like(value)
                    if parsed == 0:
                        layout_mode = ("kern", None)
                    elif parsed == -1:
                        layout_mode = ("full", None)
                    elif parsed < 0:
                        layout_mode = ("default", None)
                    else:
                        layout_mode = ("explicit", parsed)
                elif option == "w":
                    parsed = atoi_like(value)
                    if parsed > 0:
                        output_width = parsed
                elif option == "C":
                    controls_requested.append(value)
                elif option == "I":
                    info_code = atoi_like(value)
                index += index_delta
                option_index = len(argument)
                break
            write_error(f"{argv0}: invalid option -- '{option}'\n")
            write_error(usage_text(prog_name))
            return 1
        index += 1

    if info_code >= 0:
        if info_code == 0:
            sys.stdout.write(VERSION_TEXT)
            sys.stdout.write(usage_text(prog_name))
            return 0
        if info_code == 1:
            sys.stdout.write(f"{VERSION_INT}\n")
            return 0
        if info_code == 2:
            sys.stdout.write(f"{fontdir}\n")
            return 0
        if info_code == 3:
            sys.stdout.write(f"{font_name}\n")
            return 0
        if info_code == 4:
            sys.stdout.write(f"{output_width}\n")
            return 0
        if info_code == 5:
            sys.stdout.write("flf2 tlf2\n")
            return 0
        return 0

    cwd = os.getcwd()
    try:
        font_path, font_display = resolve_font_path(font_name, fontdir, cwd)
    except FileNotFoundError:
        write_error(f"{prog_name}: {font_name}: Unable to open font file\n")
        return 1
    try:
        font = parse_font(font_path, font_display)
    except FileNotFoundError:
        write_error(f"{prog_name}: {font_name}: Unable to open font file\n")
        return 1
    except ValueError:
        write_error(f"{prog_name}: {font_display}: Not a FIGlet 2 font file\n")
        return 1

    loaded_controls: List[ControlFile] = []
    for requested in controls_requested:
        try:
            control_path, control_display = resolve_control_path(requested, fontdir, cwd)
        except FileNotFoundError:
            write_error(f"{prog_name}: {strip_known_suffix(requested, ('.flc',))}: Unable to open control file\n")
            return 1
        try:
            loaded_controls.append(parse_control_file(control_path, control_display))
        except FileNotFoundError:
            write_error(f"{prog_name}: {strip_known_suffix(requested, ('.flc',))}: Unable to open control file\n")
            return 1

    if operands:
        input_bytes = build_argument_input(operands)
    else:
        input_bytes = sys.stdin.buffer.read()

    rtl = direction if direction is not None else bool(font.print_direction)
    layout = determine_layout(layout_mode, font)
    lines = render_input(
        input_bytes=input_bytes,
        font=font,
        controls=loaded_controls,
        paragraph_mode=paragraph_mode,
        german=german,
        rtl=rtl,
        justify=justify,
        output_width=output_width,
        layout=layout,
    )
    if lines:
        sys.stdout.write("\n".join(lines))
        sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
